from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, Dict, Optional

from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
    DialogueStackFrame,
)
from rasa.shared.core.flows.steps.constants import START_STEP
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.dict_access import require_keys


class InvalidMantleStackFrameType(RasaException):
    """Raised if the Mantle stack frame type is invalid."""

    def __init__(self, frame_type: Optional[str]) -> None:
        """Create an invalid Mantle stack frame type error.

        Args:
            frame_type: The invalid frame type.
        """
        super().__init__(f"Invalid stack frame type '{frame_type}'.")


class MantleStackFrameType(str, Enum):
    """How a Mantle frame relates to the frames around it.

    Shared by :class:`SkillStackFrame` and :class:`OrderedBlockStackFrame`.
    ``link`` is not a member: a ``link:`` step completes the source and pushes
    the target as ``regular``.
    """

    REGULAR = "regular"
    """Normal skill or ordered-block entry.

    Used for guided / hybrid starts, block-from-prose, and the target of a
    ``link:`` step (Mantle has no ``link`` frame type). Guided ``call:`` keeps
    the nested ``main`` block as ``regular`` even when the callee skill is
    ``call``.
    """

    INTERRUPT = "interrupt"
    """Digression: the previous top is parked while a new skill (and optional
    ``main`` block) runs. Spans multiple turns; resume may involve
    ``default_continue_interrupted``.
    """

    CALL = "call"
    """Callee skill pushed by a ``call:`` step. The caller stays on the stack
    unchanged; for guided callees the skill frame is ``call`` and the nested
    ``main`` block stays ``regular``.
    """

    INLINE_REFERENCE = "inline_reference"
    """Same-skill block park during a block switch.

    The prior ordered-block frame is silently parked (no interrupt event);
    the skill frame stays ``regular``. Unlike digression ``INTERRUPT``, this
    does not trigger ``default_continue_interrupted``.
    """

    PENDING = "pending"
    """Consumer skill waiting for a precondition resolver before activation."""

    @staticmethod
    def from_str(frame_type: Optional[str]) -> MantleStackFrameType:
        """Create a Mantle stack frame type from its persisted value.

        Args:
            frame_type: Persisted frame type, or ``None`` for a regular frame.

        Returns:
            The corresponding frame type.

        Raises:
            InvalidMantleStackFrameType: If the value is not a member.
        """
        if frame_type is None:
            return MantleStackFrameType.REGULAR
        try:
            return MantleStackFrameType(frame_type)
        except ValueError as error:
            raise InvalidMantleStackFrameType(frame_type) from error


def _previous_frame_type(data: Dict[str, Any]) -> Optional[MantleStackFrameType]:
    """Return the previous frame type stored in persisted frame data."""
    previous_raw = data.get("previous_frame_type")
    if previous_raw is None:
        return None
    return MantleStackFrameType.from_str(previous_raw)


@dataclass
class SkillStackFrame(DialogueStackFrame):
    """Represent the active prose position of a skill."""

    skill_id: str = ""
    frame_type: MantleStackFrameType = MantleStackFrameType.REGULAR
    previous_frame_type: Optional[MantleStackFrameType] = None

    @classmethod
    def type(cls) -> str:
        """Return the persisted frame type."""
        return "skill"

    def as_dict(self) -> Dict[str, Any]:
        """Serialize the frame without unset park metadata."""
        data = super().as_dict()
        if data.get("previous_frame_type") is None:
            data.pop("previous_frame_type", None)
        return data

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> SkillStackFrame:
        """Create a skill stack frame from persisted data.

        Args:
            data: Persisted frame data.

        Returns:
            The restored frame.
        """
        require_keys(data, "frame_id", "skill_id", context="Skill stack frame")
        return SkillStackFrame(
            frame_id=data["frame_id"],
            skill_id=data["skill_id"],
            frame_type=MantleStackFrameType.from_str(data.get("frame_type")),
            previous_frame_type=_previous_frame_type(data),
        )


@dataclass
class OrderedBlockStackFrame(DialogueStackFrame):
    """Represent the active step of an ordered block."""

    skill_id: str = ""
    block_id: str = ""
    step_id: str = START_STEP
    frame_type: MantleStackFrameType = MantleStackFrameType.REGULAR
    previous_frame_type: Optional[MantleStackFrameType] = None

    @classmethod
    def type(cls) -> str:
        """Return the persisted frame type."""
        return "ordered_block"

    def as_dict(self) -> Dict[str, Any]:
        """Serialize the frame without unset park metadata."""
        data = super().as_dict()
        if data.get("previous_frame_type") is None:
            data.pop("previous_frame_type", None)
        return data

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> OrderedBlockStackFrame:
        """Create an ordered-block stack frame from persisted data.

        Args:
            data: Persisted frame data.

        Returns:
            The restored frame.
        """
        require_keys(
            data,
            "frame_id",
            "skill_id",
            "block_id",
            "step_id",
            context="Ordered block stack frame",
        )
        return OrderedBlockStackFrame(
            frame_id=data["frame_id"],
            skill_id=data["skill_id"],
            block_id=data["block_id"],
            step_id=data["step_id"],
            frame_type=MantleStackFrameType.from_str(data.get("frame_type")),
            previous_frame_type=_previous_frame_type(data),
        )
